// Local eval proxy: lets promptfoo drive the Workers AI *binding* (the same
// path production uses) over an OpenAI-compatible endpoint, so the live eval
// needs nothing but `wrangler login` — no API token. AI bindings always run
// remote, so inference charges still apply to the logged-in account.
//
// Request defaults (response_format, token floor, reasoning effort) come from
// output-schema.json, regenerated by gen-schema.ts from the prompt module on
// every run — the eval always tests the current contract.
//
// Two normalizations vs what promptfoo sends:
// - promptfoo's OpenAI provider injects max_tokens 1024 + temperature 0.
//   Neither matches production: kimi-k2.5's reasoning counts against
//   max_tokens (1024 is entirely consumed by it → empty content,
//   finish_reason "length") and the app deliberately sends no sampling
//   params. Sampling params are dropped; max_tokens is floored.
// - kimi returns reasoning_content alongside content; promptfoo renders
//   reasoning as the output ("Thinking: …") and grades that instead of the
//   actual answer, so it is stripped from the response.
import config from "./output-schema.json" with { type: "json" };

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (request.method !== "POST" || url.pathname !== "/v1/chat/completions") {
      return Response.json(
        { error: "eval proxy: POST /v1/chat/completions only" },
        { status: 404 }
      );
    }
    const body = await request.json();
    const {
      temperature: _t,
      top_p: _tp,
      top_k: _tk,
      ...rest
    } = body;
    const result = await env.AI.run(rest.model, {
      messages: rest.messages,
      max_tokens: Math.max(rest.max_tokens ?? 0, config.max_tokens),
      reasoning_effort: config.reasoning_effort,
      response_format: config.response_format,
    });
    if (Array.isArray(result?.choices)) {
      for (const choice of result.choices) {
        if (choice?.message) delete choice.message.reasoning_content;
      }
    }
    return Response.json(result);
  },
};
